!function(e){function n(n){for(var t,a,o=n[0],p=n[1],c=n[2],s=0,g=[];s<o.length;s++)a=o[s],Object.prototype.hasOwnProperty.call(i,a)&&i[a]&&g.push(i[a][0]),i[a]=0;for(t in p)Object.prototype.hasOwnProperty.call(p,t)&&(e[t]=p[t]);for(d&&d(n);g.length;)g.shift()();return m.push.apply(m,c||[]),r()}function r(){for(var e,n=0;n<m.length;n++){for(var r,a=m[n],o=!0,p=1;p<a.length;p++)r=a[p],0!==i[r]&&(o=!1);o&&(m.splice(n--,1),e=t(t.s=a[0]))}return e}function t(n){if(a[n])return a[n].exports;var r=a[n]={i:n,l:!1,exports:{}};return e[n].call(r.exports,r,r.exports,t),r.l=!0,r.exports}var a={},i={33:0},m=[];t.m=e,t.c=a,t.d=function(e,n,r){t.o(e,n)||Object.defineProperty(e,n,{enumerable:!0,get:r})},t.r=function(e){"undefined"!=typeof Symbol&&Symbol.toStringTag&&Object.defineProperty(e,Symbol.toStringTag,{value:"Module"}),Object.defineProperty(e,"__esModule",{value:!0})},t.t=function(e,n){if(1&n&&(e=t(e)),8&n)return e;if(4&n&&"object"==typeof e&&e&&e.__esModule)return e;var r=Object.create(null);if(t.r(r),Object.defineProperty(r,"default",{enumerable:!0,value:e}),2&n&&"string"!=typeof e)for(var a in e)t.d(r,a,function(n){return e[n]}.bind(null,a));return r},t.n=function(e){var n=e&&e.__esModule?function(){return e.default}:function(){return e};return t.d(n,"a",n),n},t.o=function(e,n){return Object.prototype.hasOwnProperty.call(e,n)},t.p="";var o=window.webpackJsonp=window.webpackJsonp||[],p=o.push.bind(o);o.push=n,o=o.slice();for(var c=0;c<o.length;c++)n(o[c]);var d=p;m.push([212,0]),r()}({212:function(e,n,r){"use strict";r.r(n);var t=r(0);Object(t.a)("de","army",r(213),r(1))},213:function(e){e.exports=JSON.parse('{"category":[{"name":"德国","link":"de_shortcut"},{"name":"陆战武器","link":"de_army"},{"name":"火炮","link":"de_army#de_army_cannon"}],"model":"41型150mm多管火箭炮","description":"<p>41型150mm火箭炮是二战德军最早列装部队的标准型多管火箭炮，它从1940年开始量产，1941年起装备德军的火箭炮营，一直伴随德军作战至二战结束；二战期间41型150mm火箭炮一共生产了5283门。</p><p>41型150mm火箭炮有6根炮管，呈六角形布置，安装在可牵引的两轮小车上，炮管内没有膛线，但内装三根导轨来保持管内火箭弹的稳定。该炮采用有线点火装置，点火导线长18米，这样炮兵就不会被火箭弹发射时所产生的后部火焰伤害。</p><p>41型150mm火箭炮结构简单，结实耐用，可作标准化生产，生产成本低，战斗应对时间短，炮弹威力大；而且该炮重量轻，可用3吨以下的牵引车牵引运输，必要时可用人力推动，因此具有良好的机动性能。</p><p>41型150mm火箭炮主要装备德国陆军师属炮兵团，配备牵引机动车，实现全摩托化，是德军实现大密度火力覆盖的武器。在东、西线战场的进攻与防御战斗中都发挥了极大作用。但该炮射击准确性不高，且射程较短，在战场上容易被对方攻击，因此战损率也相当大。</p>","part1title":"","part1description":"","part1content":[{"image":"imgs/de/army/de_army_cannon41150_11.jpg","description":"<h6>41型150mm多管火箭炮</h6><p></p><p>技术数据：</p><p>口径：150mm；</p><p>长度：3.6米；炮管长：1.3米；重量：战斗全重770公斤，运输重量590公斤；</p><p>左右旋转角度：24度；俯仰角：-5～+45度；</p><p>有效射程：6000～7000米。</p>","caption":""},{"image":"imgs/de/army/de_army_cannon41150_12.jpg","description":"<p>41型150mm火箭弹有榴弹（如图）、燃烧弹和烟雾弹等多种，弹的初速为340米/秒。榴弹的爆炸力是同重量的炮弹的两倍。</p>","caption":""}],"part2title":"战场上的41型150mm多管火箭炮","part2description":"","part2content":[{"image":"imgs/de/army/de_army_cannon41150_21.jpg","description":"架设在两轮牵引小车上的41型150mm多管火箭炮，小车上有起倒支架，射击时要放下来固定炮身，起稳定作用，火箭炮旁还有一枚火箭弹与运输火箭弹用的弹筒。","caption":""},{"image":"imgs/de/army/de_army_cannon41150_22.jpg","description":"二战东线苏联战场，德国“大德意志”装甲掷弹兵师火箭炮连的一个41型150mm多管火箭炮阵地，炮兵正在检查火箭炮，随时准备投入战斗。","caption":""},{"image":"imgs/de/army/de_army_cannon41150_23.jpg","description":"二战东线苏联战场，德军一名41型150mm多管火箭炮炮手离火箭炮18米远处按下点火按钮，三颗火箭弹呼啸而出。","caption":""},{"image":"imgs/de/army/de_army_cannon41150_24.jpg","description":"二战东线苏联战场，德军一名炮手正在向41型150mm多管火箭炮装填最后一发火箭弹，火箭弹推入炮管后，一小段的推进部分会露在炮管外。在炮管外壁（靠装填处）可以清楚看到每个炮管都有一个长条形的点火分配器与炮管连接。","caption":""},{"image":"imgs/de/army/de_army_cannon41150_25.jpg","description":"二战北非战场，德国非洲军团遗弃在战场上的一门41型150mm多管火箭炮，一名阵亡的炮兵倒在炮架上，旁边还一发未装填的火箭弹。由于火箭炮阵地靠近最前线，因此阵地经常受到反击而造成炮毁人亡。","caption":""},{"image":"imgs/de/army/de_army_cannon41150_26.jpg","description":"二战东线苏联战场，德国武装党卫军师属炮兵团的火箭炮连一门正在战斗中的41型150mm多管火箭炮。他们可以将高爆弹或烟雾弹发射到7000码以上，大约需要90秒才能重新装载六枚火箭弹。","caption":""},{"image":"imgs/de/army/de_army_cannon41150_27.jpg","description":"1943年，东线苏联库尔斯克战场，德军火箭炮连的士兵将一门41型150mm多管火箭炮转到新阵地上的全流程。（图1）一辆半履带牵引车将火箭炮运到新阵地；（图2）炮兵将火箭炮从牵引车后卸下，移到一个合适的炮位上；（图3）在新炮位上，炮兵抓紧作好突袭射击准备。对火箭炮组来说，实现快速开火与转移，是其在战斗中生存的关键。","caption":""},{"image":"imgs/de/army/de_army_cannon41150_28.jpg","description":"二战东线苏联战场，德军一门正在发射中的41型150mm多管火箭炮，火箭炮旁边地面上还有大量未装填的火箭弹。41型150mm多管火箭炮的6枚火箭弹可作多发齐射或单发顺序发射，顺序发射时每发间隔时间为2秒，重装6发炮弹需要90秒。","caption":""},{"image":"imgs/de/army/de_army_cannon41150_29.jpg","description":"二战东线苏联战场，德国武装党卫军炮兵团的一个41型150mm多管火箭炮阵地，炮兵正在加快速度装弹，准备下一轮发射；由于火箭弹射程较短，因此火箭炮每完成一轮发射，就要迅速转移阵地，否则容易因阵地暴露而遭到苏军反击。","caption":""},{"image":"imgs/de/army/de_army_cannon41150_30.jpg","description":"二战东线苏联战场，德军一个41型150mm多管火箭炮的新阵地，炮兵忙着安装点火导线，作好射击准备。随着二战中后期苏联战场的战事不断激烈，德军更迫切地需要携带便利、且有大面积火力覆盖威力的火箭炮。因此至1942年，东线配备的炮兵团数量也在不断增加。","caption":""},{"image":"imgs/de/army/de_army_cannon41150_31.jpg","description":"二战东线苏联战场，德军一辆半履带装甲车牵引着一门41型150mm多管火箭炮进行阵地转移。由于该型火箭炮重量较轻，因此用具有1吨至3吨牵引力的轻型半履带车即可进行牵引运输。","caption":""}]}')}});